from pathlib import Path
from html import escape
root=Path(__file__).parent
nav=[('index.html','Startseite'),('entdecken.html','Arista entdecken'),('leben.html','Leben in Arista'),('mitspielen.html','Mitspielen'),('kontakt.html','Kontakt')]
def tile(label,title,txt,href):return f'<article class="tile"><span class="count">{label}</span><h3>{title}</h3><p>{txt}</p><a href="{href}">Mehr erfahren →</a></article>'
def page(file,title,subtitle,body,home=False):
 links=''.join(f'<a href="{h}"'+(' aria-current="page"' if h==file else '')+f'>{t}</a>' for h,t in nav)
 html=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Arista – bodenständiges Low-Fantasy-LARP-Königreich und Teil der Mittellande-Kampagne."><title>{escape(title)} | Arista – LARP</title><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#inhalt">Zum Inhalt springen</a><div class="topbar"><div class="topinner"><span>Low-Fantasy · Rittertum · Gemeinschaft</span><span>Deutsch · weitere Sprachen geplant</span></div></div><header class="brandbar"><div class="brandinner"><a class="brand" href="index.html" aria-label="Arista Startseite"><span class="emblem" aria-hidden="true">A</span><span><strong>ARISTA</strong><small>Das Königreich im LARP</small></span></a><button class="menu" aria-controls="primary-nav" aria-expanded="false">☰ Menü</button><nav id="primary-nav" aria-label="Hauptnavigation">{links}</nav></div></header><section class="banner"><div class="wrap"><div class="eyebrow">{'Willkommen im Königreich' if home else 'Das Königreich Arista'}</div><h1>{escape(title)}</h1><p>{escape(subtitle)}</p></div></section><main class="wrap main" id="inhalt">{body}</main><footer class="footer"><div class="wrap footerinner"><p>Arista · LARP-Land der Mittellande-Kampagne<br><small>Unverbindlicher Designprototyp · Stand: Version A</small></p><p><a href="mitspielen.html">Mitspielen</a> &nbsp;·&nbsp; <a href="kontakt.html">Kontakt</a> &nbsp;·&nbsp; <a href="index.html">Startseite</a></p></div></footer><script src="assets/script.js" defer></script></body></html>'''
 (root/file).write_text(html,encoding='utf-8')
page('index.html','Arista. Ein Land voller Geschichten.','Ein bodenständiges Low-Fantasy-Königreich, geprägt von Rittertum, Naturverbundenheit und einer lebendigen Spielwelt.',f'''<div class="intro"><div class="eyebrow">Ein Reich zum Entdecken</div><p class="lead">Arista ist ein LARP-Land der Mittellande-Kampagne. Hier treffen ritterliche Ideale, politische Interessen und persönliche Geschichten aufeinander.</p><p>Das Königreich orientiert sich am maurischen Spanien des 12. und 13. Jahrhunderts und an einer Landschaft, die von den Pyrenäen inspiriert ist. Im Mittelpunkt stehen intensives Charakterspiel und die Entwicklung einer fortlaufenden Geschichte.</p><a class="button" href="mitspielen.html">Ich möchte mitspielen</a><a class="button ghost" href="entdecken.html">Das Königreich entdecken</a></div><section class="section"><div class="eyebrow">Zwei Wege nach Arista</div><h2>Was möchtest du erfahren?</h2><div class="grid two">{tile('01 · DIE WELT','Das Königreich kennenlernen','Geschichte, Landschaften und die Landesteile Aristas entdecken.','entdecken.html')}{tile('02 · DIE GEMEINSCHAFT','Teil der Geschichte werden','Erfahre, für wen Arista geeignet ist und wie du den ersten Kontakt aufnimmst.','mitspielen.html')}</div></section><section class="section"><h2>Eine Welt mit eigenem Charakter</h2><div class="grid">{tile('DIE LANDSCHAFT','Zwischen Bergen und Meer','Pireneos, Dunkelwasser und neu erschlossene Grenzregionen.','regionen.html')}{tile('DIE GESELLSCHAFT','Rittertum und Kronrat','Ein kleines Adelshausgefüge und der starke Einfluss des Ritterstands.','leben.html')}{tile('DER GLAUBE','Die Dame vom See','Ein Glaube, der Ehre, Tugend und den Alltag Aristas prägt.','religion.html')}</div></section><section class="section"><blockquote class="quote">„Ein Land für alle, die nicht nur Abenteuer suchen – sondern Teil einer fortlaufenden Geschichte werden wollen.“</blockquote></section>''',True)
page('entdecken.html','Arista entdecken','Geschichte, Landschaften und die Besonderheiten des Königreichs.',f'''<p class="lead intro">Arista ist ein überwiegend gebirgiges Reich mit fruchtbaren Tälern, Küstenregionen und einem noch nicht vollständig erschlossenen Osten.</p><section class="section"><div class="grid">{tile('LAND UND LEUTE','Die Regionen','Die Pireneos, die Küste am Dunkelwasser und das Landesinnere.','regionen.html')}{tile('GESCHICHTE','Wandel und Bedrohungen','Die Geschichte des Reiches ist geprägt von Auseinandersetzungen um Herrschaft und Grenzen.','geschichte.html')}{tile('GESCHICHTEN AUS ARISTA','Leben im Königreich','Herrschaft, Gesellschaft, Religion und Kultur.','leben.html')}</div></section>''')
page('regionen.html','Land und Regionen','Die Landschaften Aristas – von den Pireneos bis zum Dunkelwasser.','''<div class="crumbs"><a href="entdecken.html">Arista entdecken</a> / Land und Regionen</div><div class="split"><aside class="side" aria-label="Abschnitte"><a href="#pireneos">Die Pireneos</a><a href="#kueste">Die Küste</a><a href="#osten">Der Osten</a><a href="#inneres">Das Landesinnere</a></aside><article class="prose"><p class="lead">Arista ist überwiegend gebirgig. Die Pireneos prägen Westen und Norden, im Süden liegt die Küste des Dunkelwassers.</p><h2 id="pireneos">Die Pireneos</h2><p>Dichte Nadel- und Mischwälder, hohe Gipfel, zahlreiche Seen und Höhlen prägen die Gebirgsregion. Die Bäche und Flüsse speisen unter anderem die La Onda Negra, an deren Ufern fruchtbare Ebenen liegen.</p><h2 id="kueste">Die Küstenregion</h2><p>Im Süden liegen Fischerdörfer und befestigte Kastelle am Dunkelwasser. Steile Küstenabschnitte und Buchten bestimmen die Landschaft.</p><h2 id="osten">Der Osten</h2><p>Der Osten ist in weiten Teilen noch unerschlossen. Neue Siedlungen und Expeditionen spielen für die jüngere Entwicklung Aristas eine wichtige Rolle.</p><h2 id="inneres">Das Landesinnere</h2><p>Bergseen, Höhlen, Klöster und kleinere Burgen prägen das Landesinnere.</p><p class="note">Im Prototyp sind die Landschaftsbeschreibungen bewusst zusammengefasst. Ausführliche Ergänzungstexte aus dem Ausgangsdokument können nach redaktioneller Prüfung hinzukommen.</p><a href="entdecken.html">← Zurück zu Arista entdecken</a></article></div>''')
page('geschichte.html','Geschichte Aristas','Ein Königreich, dessen Geschichte von Wandel und Konflikten geprägt ist.','''<div class="crumbs"><a href="entdecken.html">Arista entdecken</a> / Geschichte</div><article class="prose"><p class="lead">Aristas Geschichte ist geprägt vom Kampf gegen Unterdrückung und Fremdherrschaft, insbesondere durch die Moros.</p><h2>Ein Land im Wandel</h2><p>Seit 1215 werden neue Grenzregionen im Osten und Norden erschlossen. Expeditionen, Siedlungsgründungen und die Einbindung zuvor abgelegener Gebiete prägen die jüngere Geschichte.</p><h2>Aktuelle Bedrohungen</h2><p>In neu erschlossenen Gebieten kommt es zu Überfällen. Nach manchen Angriffen bleibt ein rätselhaftes Zeichen zurück: zwei rote Punkte.</p><a href="regionen.html">Die Landschaften Aristas entdecken →</a></article>''')
page('leben.html','Leben in Arista','Wie Herrschaft, Glaube und Alltag im Königreich zusammenwirken.',f'''<p class="lead intro">Das Leben in Arista ist geprägt von ritterlichen Idealen, einer vielgestaltigen Landschaft und dem Einfluss der Dama de Lago.</p><section class="section"><div class="grid">{tile('HERRSCHAFT','Krone und Kronrat','Eine feudalistische Monarchie mit ersten konstitutionellen Elementen; der Ritterstand besitzt große Bedeutung.','herrschaft.html')}{tile('GLAUBE','Die Dama de Lago','Ritterlichkeit, Tugend und Ehre sind wichtige Werte des verbreiteten Glaubens.','religion.html')}{tile('ALLTAG','Gesellschaft und Wirtschaft','Landwirtschaft, Viehzucht, Fischerei, Bergbau und Handel bestimmen das Leben vieler Menschen.','alltag.html')}</div></section>''')
page('herrschaft.html','Herrschaft und Gesellschaft','Die Menschen und Machtstrukturen des Königreichs.','''<div class="crumbs"><a href="leben.html">Leben in Arista</a> / Herrschaft und Gesellschaft</div><article class="prose"><p class="lead">Arista ist eine feudalistische Monarchie mit ersten konstitutionellen Elementen.</p><h2>Das Königspaar</h2><p>König Inigo III. „der Weise“ aus dem Hause Irati und Königin Angelica I. „die Gnädige“ aus dem Hause Hecho stehen an der Spitze des Reiches.</p><h2>Der Kronrat</h2><p>Im Kronrat sind die Herrschaft, die Landesteile und ein Vertreter der Kirche der Dame repräsentiert. Der Ritterstand ist gesellschaftlich von großer Bedeutung.</p><h2>Die Bevölkerung</h2><p>In den Bergregionen überwiegen Viehzucht, Bergbau und traditionell geprägte Gemeinschaften. In den Tälern und an der Küste spielen Landwirtschaft, Fischerei und Handel eine größere Rolle.</p><p class="note">Namen, Titel und die Gliederung einzelner Landesteile sind für diesen Prototyp nicht redaktionell abgeglichen.</p></article>''')
page('religion.html','Der Glaube an die Dame','Religion, Werte und Bräuche in Arista.','''<div class="crumbs"><a href="leben.html">Leben in Arista</a> / Der Glaube</div><div class="split"><aside class="side" aria-label="Abschnitte"><a href="#dama">La Dama de Lago</a><a href="#kirche">Die Kirche</a><a href="#alltag">Religion im Alltag</a></aside><article class="prose"><p class="lead">Der Glaube an die Dama de Lago – die Herrin des Sees – ist die vorherrschende Religion Aristas.</p><h2 id="dama">La Dama de Lago</h2><p>Der Glaube betont Ritterlichkeit, Tugend, Ehre und Tapferkeit. Andere „gute und gerechte“ Gottheiten werden grundsätzlich toleriert.</p><h2 id="kirche">Die Rolle der Kirche</h2><p>Der Klerus ist überwiegend weiblich, schließt Männer aber nicht aus. Ein Vertreter der Kirche gehört dem Kronrat an.</p><h2 id="alltag">Glaube im Alltag</h2><p>Gebete und Segnungen begleiten Reisen, Ernten und wichtige Lebensentscheidungen. Feste, Pilgerreisen und gemeinsame Andachten stärken die Dorfgemeinschaft.</p><a href="leben.html">← Zurück zu Leben in Arista</a></article></div>''')
page('alltag.html','Alltag und Wirtschaft','Das Leben von Handwerkern, Bauern, Händlern und anderen Bewohnern Aristas.','''<div class="crumbs"><a href="leben.html">Leben in Arista</a> / Alltag und Wirtschaft</div><article class="prose"><p class="lead">Wirtschaftlich basiert das Reich auf Landwirtschaft, Viehzucht, Fischerei, Bergbau und Handel.</p><h2>Regionale Lebensweisen</h2><p>In den Hochlagen werden Schafe und Ziegen gehalten; in den Tälern liegen landwirtschaftlich nutzbare Flächen. Handel findet auch entlang der La Onda Negra statt.</p><h2>Währung</h2><p>Arista besitzt eine eigene Währung. Der „Goldpfennig“ zeigt den Kelch der Dame vom See und den Stierschädel von Tauro Fuego. Daneben sind weitere Handelswährungen und Münzen der Mittellande im Umlauf.</p><h2>Kultur und Feste</h2><p>Im Ausgangsmaterial werden unter anderem Frühlings-, Sommer- und Winterfest sowie Erntedank und Viehmarkt genannt.</p></article>''')
page('mitspielen.html','Mitspielen in Arista','Du möchtest Teil der Geschichte werden? Hier beginnt dein Weg.','''<div class="intro"><span class="tag">Für neue Spielerinnen und Spieler</span><p class="lead">Arista bietet Raum für intensives Charakterspiel, politische und gesellschaftliche Geschichten sowie persönliche Entwicklung.</p><h2>Was erwartet dich?</h2><p>Ein bodenständiges Low-Fantasy-Setting mit idealisiertem Rittertum, einer lebendigen Spielwelt und einer starken Gemeinschaft. Die Hauptspielgegend liegt in Nordrhein-Westfalen und Hessen.</p><h2>Kann ich neu einsteigen?</h2><p>Ja – neue Mitspielende sind grundsätzlich willkommen, allerdings nach vorheriger Absprache mit der Gruppe.</p><h2>Was ist LARP?</h2><p>LARP steht für Live Action Role Playing. Menschen schlüpfen in Rollen und spielen gemeinsam Geschichten in einer ausgestalteten Welt. Konkrete Regeln und Abläufe unterscheiden sich je nach Gruppe und Veranstaltung.</p><p class="note">Die praktische Einstiegsanleitung, Kontaktkanäle und mögliche nächste Termine wurden im vorliegenden Material noch nicht konkretisiert.</p><a class="button" href="kontakt.html">Kontakt und nächste Schritte</a><a class="button ghost" href="entdecken.html">Zuerst die Welt kennenlernen</a></div>''')
page('kontakt.html','Kontakt','Fragen zum Land Arista oder zum Einstieg in unsere LARP-Gruppe?','''<div class="intro"><p class="lead">Der Einstieg in Arista erfolgt nach Absprache. Wir möchten neuen Interessierten die Gelegenheit geben, das Spielkonzept und die Gruppe kennenzulernen.</p><h2>So erreichen Sie uns</h2><p class="note">Im bereitgestellten Dokument ist noch kein konkreter Kontaktweg eingetragen. Hier wird später eine bestätigte E-Mail-Adresse oder ein Kontaktformular eingebunden.</p><h2>Bis dahin: Arista erkunden</h2><a class="button" href="mitspielen.html">Informationen zum Mitspielen</a><a class="button ghost" href="index.html">Zur Startseite</a></div>''')
print('Created',len(list(root.glob('*.html'))),'html files')
